  /* 29.09.2026 владелец: «колдуна крупнее — он меньше всех; может поднять
     свой посох, когда ты мимо пробегаешь, а огонь на нём чтобы горел ярче
     зелёным». Рост 2,8: в прежние 2,3 входил посох, и сам колдун под капюшоном
     был около 2,1 м. Посох с кулаком — на своей кости (оснастить), опора
     в кулаке; огонь навершия едет на ней же (пятое поле точки огня). */
