  'обочина-склеп': 5.8,        // семейный склеп с деревом
  'обочина-толпа': 4.4,        // тесная толпа плит, крестов и обелиск
  'обочина-ворота': 5.6,       // разрушенные ворота с воронами
  'обочина-плакальщица': 5.0,  // плачущий ангел за оградой
  /* Высокие одиночные деревья с узким основанием — у самой ограды. */
  'обочина-высокое-1': 9.6, 'обочина-высокое-2': 9.2,
  'обочина-высокое-3': 9.0, 'обочина-высокое-4': 9.4
