  'подземелье-ниши': 4.4,        // стена с нишами, полными черепов, и свечами
  'подземелье-прикованный': 3.8, // скелет, прикованный к обломку стены
  'подземелье-решётка': 4.6,     // ржавая решётка с шипами в каменной арке
  'подземелье-колонна': 4.8,     // колонна с горящим факелом и цепями
  'подземелье-гробы': 2.1,       // гнилые гробы штабелем, один приоткрыт
