  'замок-доспехи': 3.0,          // рыцарские доспехи на подставке, с алебардой
  'замок-канделябр': 3.2,        // кованый напольный канделябр со свечами
  'замок-люстра': 2.0,           // рухнувшая хрустальная люстра, свечи ещё горят
  'замок-стол': 1.8,             // пиршественный стол, рваная скатерть, кубки
  'замок-трон': 3.4,             // трон с крыльями летучей мыши и черепами
  'замок-горгулья': 3.6,         // каменная горгулья на постаменте
