/* Задники подземелья и замка (30.09.2026): вид вглубь тоннеля и зала, висит
   далеко впереди за туманом, как картина с замком на кладбище. `схождение` —
   где на картинке точка схода, в долях высоты сверху: её ставим на уровень
   глаз камеры, чтобы тоннель на картине продолжал настоящий. */
